<?php class DashboardController extends Controller{function index(){$this->auth();$db=Database::db();$role=$_SESSION['user']['role_name'];$uid=$_SESSION['user']['id'];$stats=[];$rows=[];if($role==='super_admin'){$stats=['Doctors'=>$db->query('SELECT COUNT(*) FROM doctors')->fetchColumn(),'Hospitals'=>$db->query('SELECT COUNT(*) FROM hospitals')->fetchColumn(),'Appointments'=>$db->query('SELECT COUNT(*) FROM appointments')->fetchColumn(),'Open Emergencies'=>$db->query('SELECT COUNT(*) FROM emergency_incidents WHERE status NOT IN ("closed","cancelled")')->fetchColumn(),'Pending Doctors'=>$db->query('SELECT COUNT(*) FROM doctors WHERE verification_status="pending"')->fetchColumn(),'Ambulances'=>$db->query('SELECT COUNT(*) FROM ambulances')->fetchColumn()];}elseif($role==='patient'){$q=$db->prepare('SELECT COUNT(*) FROM appointments WHERE patient_user_id=?');$q->execute([$uid]);$stats=['My Appointments'=>$q->fetchColumn(),'Approved Doctors'=>$db->query('SELECT COUNT(*) FROM doctors WHERE verification_status="approved"')->fetchColumn(),'Hospitals'=>$db->query('SELECT COUNT(*) FROM hospitals WHERE status="active"')->fetchColumn(),'Emergency'=>'SOS'];}elseif($role==='doctor'){$q=$db->prepare('SELECT id,verification_status FROM doctors WHERE user_id=?');$q->execute([$uid]);$d=$q->fetch(PDO::FETCH_ASSOC);$did=$d['id']??0;$a=$db->prepare('SELECT COUNT(*) FROM appointments WHERE doctor_id=? AND appointment_date=CURDATE()');$a->execute([$did]);$b=$db->prepare('SELECT COUNT(*) FROM appointments WHERE doctor_id=? AND appointment_date>=CURDATE() AND status="booked"');$b->execute([$did]);$stats=['Today Patients'=>$a->fetchColumn(),'Upcoming'=>$b->fetchColumn(),'Verification'=>ucfirst($d['verification_status']??'pending'),'Emergency Requests'=>$db->query('SELECT COUNT(*) FROM emergency_incidents WHERE status IN ("reported","alerted")')->fetchColumn()];}else{$stats=['Hospitals'=>$db->query('SELECT COUNT(*) FROM hospitals')->fetchColumn(),'Appointments'=>$db->query('SELECT COUNT(*) FROM appointments')->fetchColumn(),'Emergencies'=>$db->query('SELECT COUNT(*) FROM emergency_incidents')->fetchColumn(),'Ambulances'=>$db->query('SELECT COUNT(*) FROM ambulances')->fetchColumn()];}$this->view('dashboard',['stats'=>$stats,'role'=>$role]);}}